const KEY='orbyte-flow-demo-v1';
let s;try{s=JSON.parse(localStorage.getItem(KEY));if(s?.version!==1)s=null;}catch{}s??=initialState();migrateCustomerService(s);
let loginAudience='staff';
let page='dashboard',tab='leave',room='交付协作',selectedRole='owner',importRows=[],toastTimer,messageTimer;
const $=q=>document.querySelector(q),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={settings:'M12 8a4 4 0 110 8 4 4 0 010-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',inbox:'M4 4h16v16H4z M4 13h5l2 3h2l2-3h5',check:'M5 12l4 4L19 6',people:'M16 21v-2a4 4 0 00-4-4H6a4 4 0 00-4 4v2 M9 11a4 4 0 100-8 4 4 0 000 8 M17 4a4 4 0 010 7 M22 21v-2a4 4 0 00-3-4',work:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18',chat:'M3 3h18v14H9l-6 4z M7 8h10 M7 12h6',connect:'M9 7V3 M15 7V3 M6 7h12v5a6 6 0 01-12 0z M12 18v4',logs:'M5 3h14v18H5z M9 7h6 M9 12h6 M9 17h4',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',arrow:'M4 12h16 M14 6l6 6-6 6',plus:'M12 5v14 M5 12h14',bell:'M18 8a6 6 0 00-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',clock:'M12 8v5l3 2 M22 12a10 10 0 11-20 0 10 10 0 0120 0',box:'M3 6l9-4 9 4v12l-9 4-9-4z M3 6l9 5 9-5 M12 11v11',menu:'M3 6h18 M3 12h18 M3 18h18',x:'M6 6l12 12 M18 6L6 18',leaf:'M20 3C4 2 2 9 5 16s14 4 15-13z M5 20L16 8',upload:'M12 16V3 M7 8l5-5 5 5 M3 16v5h18v-5',money:'M3 5h18v14H3z M15 12a3 3 0 11-6 0 3 3 0 016 0',calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 10h18'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.spark}"/></svg>`;
const btn=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const badge=(text,type='')=>`<span class="tag ${type}">${esc(text)}</span>`;
const person=id=>s.staff.find(e=>e.id===id)?.name||id;
const accountUI=createAccountUI({getState:()=>s,esc,icon,btn,badge,heading,modal});
const customerUI=createCustomerUI({getState:()=>s,esc,icon,btn,badge,heading,modal});
function applyPreferences(){const p=can(s,'profile')?currentProfile(s):{};document.documentElement.dataset.density=p.compact?'compact':'comfortable';document.documentElement.dataset.reduceMotion=String(!!p.reducedMotion);document.documentElement.dataset.reduceTransparency=String(!!p.reduceTransparency);}
function profileAvatar(){const p=currentProfile(s);return p.avatar?`<img src="${p.avatar}" alt="个人头像">`:esc(s.session.name.slice(0,1));}
const time=v=>new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Kuala_Lumpur',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const status=x=>badge(({pending:'待审批',approved:'已批准',rejected:'已驳回',new:'待分析',review:'待主管确认'})[x]||x,['pending','review','受阻'].includes(x)?'orange':x==='rejected'?'red':'');
const empty=t=>`<div class="empty">${esc(t)}</div>`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(s));}catch{toast('浏览器无法保存数据，本次更改只在当前会话保留。');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4300);}
function modal(title,body){rememberModalTrigger();$('#modal').setAttribute('aria-labelledby','dialog-title');$('#modal').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button aria-label="关闭" class="icon-button" data-action="close">${icon('x')}</button></div>${body}`;$('#modal').showModal();}
function close(){$('#modal').close();}
function recordError(e){toast(e.message);if(s.session)addLog(s,'error','操作未完成',e.message,'operations');persist();}
const navs=[['dashboard','home','工作概览'],['inbox','inbox','客户收件箱'],['approvals','check','审批中心'],['people','people','People · 人事'],['work','work','Work · 项目'],['chat','chat','团队聊天'],['broadcast','bell','企业主通知'],['connect','connect','Connect · 集成'],['logs','logs','活动与洞察'],['strategy','leaf','产品与路线'],['settings','settings','设置']];
function login(){return `<div class="login"><section class="login-art"><div class="brand"><i class="brand-mark"></i>Nexus <em>workspace</em></div><h1>Nexus。<br>让工作<span>自然流动。</span></h1><p>把客户消息变成明确的下一步。连接团队、订单与审批，让小企业的每一次交付都有人接住。</p><div class="orbit"><span class="float-label one">消息 → 工作</span><div class="orbit-center">${icon('spark')}</div><span class="float-label two">决定权，留给人</span></div><div class="login-foot">BUILT FOR MALAYSIAN SMALL BUSINESSES · NAILONG 2026</div></section><section class="login-panel"><div class="login-entry"><div class="entry-tabs" role="group" aria-label="登录入口"><button type="button" data-action="login-audience" data-audience="staff" class="${loginAudience==='staff'?'active':''}" aria-pressed="${loginAudience==='staff'}">员工入口</button><button type="button" data-action="login-audience" data-audience="customer" class="${loginAudience==='customer'?'active':''}" aria-pressed="${loginAudience==='customer'}">客户入口</button></div>${loginAudience==='customer'?customerUI.loginForm():`<form class="login-form" id="login-form"><div class="eyebrow">YOUR WORK, CONNECTED</div><h2>欢迎来到你的工作中心</h2><p class="intro">先告诉我们你的职位与姓名，为你呈现相关工作。</p><label for="login-role" class="sr-only">选择职位</label><div class="roles" role="group" aria-label="选择职位">${Object.entries(roles).map(([k,r])=>`<button type="button" class="role-option ${k===selectedRole?'selected':''}" data-action="role" data-id="${k}" aria-pressed="${k===selectedRole}"><b>${r.label}</b><small>${r.desc}</small></button>`).join('')}</div><div class="field"><label for="login-name">你的姓名</label><input id="login-name" name="name" placeholder="请输入姓名" maxlength="40" required autocomplete="name" value="${esc(s.profiles?.[roles[selectedRole].staff]?.displayName||roles[selectedRole].name)}"></div><div class="field"><label for="business-industry">企业类型</label><select id="business-industry" name="industry"><option>印刷与定制礼品</option><option>小型零售</option><option>专业服务</option><option>餐饮与烘焙</option></select></div><button class="btn login-submit" type="submit">进入工作空间 ${icon('arrow')}</button><div class="footer-note">黑客松演示 · 姓名只保存在此浏览器。职位选择模拟平台身份，不是真实登录认证。各职位绑定固定演示员工，完整数据不应存放在前端。</div></form>`}</div></section></div>`;}
function render(){applyPreferences();if(s.session&&page==='chat'&&!conversationMembers(s,room).includes(staffId(s)))room='交付协作';if(!s.session){document.body.classList.remove('navigation-open');$('#app').innerHTML=login();return;}if(s.session.role==='customer'){document.body.classList.remove('navigation-open');hideMessage();$('#app').innerHTML=customerUI.portal();return;}if(!can(s,page))page='dashboard';const nav=navs.find(n=>n[0]===page)||['profile','people','个人中心'];const pending=s.inquiries.filter(q=>q.status==='review').length;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar" aria-label="工作空间导航"><div class="brand"><i class="brand-mark"></i>Nexus <em>workspace</em></div><div class="workspace"><div class="avatar">K</div><div><b style="font-size:11px">${esc(companySettings(s).name)}</b><br><span>${esc(companySettings(s).state)} · ${esc(s.industry)}</span></div></div><div class="nav-label">WORKSPACE</div><nav class="nav">${navs.filter(n=>can(s,n[0])).map(([p,i,l])=>`<button data-action="nav" data-page="${p}" class="${p===page?'active':''}" ${p===page?'aria-current="page"':''}>${icon(i)}<span>${l}</span>${p==='chat'&&currentProfile(s).chatBadges&&unreadMessages(s).length?`<b class="count">${unreadMessages(s).length}</b>`:''}${p==='inbox'?`<b class="count">${s.inquiries.filter(q=>q.status!=='approved').length}</b>`:p==='approvals'&&pending?`<b class="count">${pending}</b>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="side-help"><strong>小团队，也能从容交付。</strong><br>从一条客户消息开始，把琐事交给流程。</div><button class="user-button" data-action="account-menu" aria-label="打开个人账户菜单"><div class="avatar user-avatar">${profileAvatar()}</div><div><b style="font-size:11px">${esc(s.session.name)}</b><br><small>${roles[s.session.role].label} · 个人中心</small></div><span style="margin-left:auto">↗</span></button></div></aside><button class="nav-scrim" data-action="menu" aria-label="关闭导航" tabindex="-1" hidden></button><main class="main" id="main-content" tabindex="-1"><header class="topbar"><button class="icon-button mobile-menu" aria-label="打开导航" aria-controls="sidebar" aria-expanded="false" data-action="menu">${icon('menu')}</button><div class="crumb">工作空间 <span style="margin:0 12px">/</span> <b>${nav[2]}</b></div><div class="top-actions"><span class="demo-dot">演示模式 · 合成业务数据</span><button class="icon-button" aria-label="查看待办通知" data-action="notifications">${icon('bell')}</button><button class="avatar user-avatar profile-trigger" data-action="account-menu" aria-label="打开个人中心" title="个人中心">${profileAvatar()}</button></div></header><div class="content">${({dashboard,people,work,chat,inbox,approvals,connect,logs,strategy,broadcast,profile:accountUI.profile,settings:accountUI.settings})[page]()}</div></main></div>`;
 syncNavigation();
}
function heading(k,title,sub,action=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1 tabindex="-1">${title}</h1><p>${sub}</p></div>${action}</div>`;}
function stat(title,value,note,i){return `<div class="stat"><div class="stat-top">${title}<span class="stat-icon">${icon(i)}</span></div><strong>${value}</strong><small>${note}</small></div>`;}
function flow(q){const n=q?.status==='approved'?5:q?.status==='review'?3:1;return `<div class="workflow">${['客户请求','业务信息','生成建议','人工审批','创建任务'].map((t,i)=>`${i?'<span class="step-arrow">›</span>':''}<div class="step ${i<n?'done':''}"><b>${i<n?icon('check').replace('<svg','<svg width="13" height="13"'):(i+1)}</b>${t}</div>`).join('')}</div>`;}
function taskRows(tasks){return tasks.map(t=>`<div class="row"><div class="row-main"><div class="round-icon ${t.status==='受阻'?'orange':''}">${icon('work')}</div><div><h3>${esc(t.title)}</h3><p>${esc(t.customer)} · ${esc(person(t.assignee))} · ${esc(t.due)}</p></div></div><div class="row-end">${status(t.status)}</div></div>`).join('')||empty('暂时没有分配给你的任务。');}
function workPreview(tasks){
 const task=tasks.find(t=>t.status==='受阻')||tasks.find(t=>t.status!=='已完成')||tasks[0];
 return `<div class="workflow-preview"><div class="preview-head"><span>${icon('work')} 当前工作</span><small>与你相关的项目</small></div>${task?`<div class="preview-title">${esc(task.title)}</div><div class="preview-step">${icon('people')} ${esc(person(task.assignee))}<small>项目负责人</small></div><div class="preview-step">${icon('calendar')} ${esc(task.due)}<small>交付日期</small></div><div class="preview-step">${icon(task.status==='受阻'?'clock':'check')} ${esc(task.status)}<small>${task.status==='受阻'?'需要关注':task.status==='已完成'?'进度已完成':'持续推进'}</small></div>`:`<div class="preview-title">今天，从容开始。</div><p class="footer-note">还没有与你相关的项目。新任务分配后，会出现在这里。</p>`}</div>`;
}
function dashboard(){const ts=visibleTasks(s),ls=visibleLogs(s),sum=monthlySummary(s),own=staffId(s),pending=visibleRequests(s,'leave').filter(x=>x.status==='pending').length+visibleRequests(s,'claims').filter(x=>x.status==='pending').length+visibleRequests(s,'ot').filter(x=>x.status==='pending').length+(can(s,'business-review')?s.inquiries.filter(q=>q.status==='review').length:0);
 return heading('MAKE ROOM FOR WHAT MATTERS',`${esc(s.session.name)}，把今天安排好。`,'团队的工作、需要你确认的事，都在这里。',can(s,'create-inquiry')?btn(`${icon('plus')} 新建客户请求`,'new-inquiry'):btn(`${icon('plus')} 记录今日工作`,'daily'))+`<section class="hero"><div><div class="eyebrow">LESS BUSYWORK. MORE PROGRESS.</div><h2>少一点跟进。<br>多一点进展。</h2><p>把客户需求、团队安排和审批连接起来。重要的决定，始终由你掌握。</p>${btn(`查看${can(s,'inbox')?'客户需求':'我的项目'} ${icon('arrow')}`,'nav','', 'data-page="'+(can(s,'inbox')?'inbox':'work')+'"')}</div>${workPreview(ts)}</section><div class="stats">${stat('需要你关注',pending,'申请与业务审批待办','check')}${stat('相关进行中任务',ts.filter(t=>t.status!=='已完成').length,`${ts.filter(t=>t.status==='受阻').length} 项存在阻碍`,'work')}${stat('本月审批事件',sum.approvals,'基于你可查看的活动记录','clock')}${stat('我的年假余额',Math.max(0,policy(s).annualLeaveDays-s.leave.filter(l=>l.staff===own&&l.status==='approved').reduce((n,l)=>n+l.days,0))+' 天',`演示政策：每年 ${policy(s).annualLeaveDays} 天`,'leaf')}</div><div class="columns"><div><section class="card"><div class="card-head"><h2>今天，先做好这几件事</h2>${btn('查看项目 →','nav','ghost','data-page="work"')}</div>${taskRows(ts.slice(0,3))}</section><section class="card"><div class="card-head"><h2>从客户消息到交付</h2>${badge('核心自动化')}</div>${flow(s.inquiries[0])}<div class="insight"><strong>为什么先确认，再执行？</strong><br>以 Bunga Café 加急订单为例：库存不足 20 个，Daniel 在交付日休假。规则会同时检查这两个条件，建议交给可用的 Amir，并等待主管审批。</div></section></div><div><section class="card"><div class="card-head"><h2>工作脉搏</h2>${badge('演示基线','gray')}</div><div class="mini-chart">${[35,57,42,73,61,89,55].map((v,i)=>`<div class="bar-wrap"><div class="bar ${i===5?'current':''}" style="height:${v}px"></div>${['一','二','三','四','五','六','日'][i]}</div>`).join('')}</div><p class="footer-note">示意图，非实际业务统计。真实效果将以完成耗时、遗漏率和返工率衡量。</p></section><section class="card"><div class="card-head"><h2>最近发生</h2>${btn('全部 →','nav','ghost','data-page="logs"')}</div>${ls.slice(0,3).map(l=>`<div class="timeline"><span class="timeline-dot"></span><div><h3>${esc(l.title)}</h3><p>${esc(l.detail)}</p><time>${time(l.time)} · ${esc(l.actor)}</time></div></div>`).join('')||empty('完成第一项操作后，这里会留下记录。')}</section><div class="insight"><strong>连接，而不是增加负担。</strong><br>以 Orbyte 的 People、Work、Connect 为上下文，给小团队增加客户需求到履约的新能力。</div></div></div>`;}
function inbox(){const support=can(s,'create-inquiry');return heading('CUSTOMER REQUESTS',support?'从客户消息，到明确交接。':'客服已整理的客户请求。',support?'在客户对话中确认需求，建立请求后交给执行员工和审批负责人。':'查看客服建立的请求与建议，重要方案由负责人确认。',support?btn(`${icon('plus')} 新建客户请求`,'new-inquiry'):'')+(support?customerUI.supportPanel():'')+`<div class="card-head"><h2>客户请求</h2>${badge(s.inquiries.length+' 项','gray')}</div><div class="grid2">${s.inquiries.map(q=>`<section class="card"><div class="card-head"><div><h2>${esc(q.customer)}</h2><small>${esc(q.id)} · ${esc(q.source)}</small></div>${status(q.status)}</div><div class="notice">${esc(q.text)}</div>${flow(q)}${q.plan?`<div class="insight ${q.plan.missing?'warning':''}"><strong>业务核对与交接</strong><br>${esc(q.plan.reason)}<br>建议执行：${esc(q.plan.assignee?person(q.plan.assignee):'暂无可用员工')}<br>审批负责人：${esc(q.reviewer?person(q.reviewer):'管理者')}<br>${esc(q.plan.decision)}；未承诺交期或报价。</div>`:''}<div class="actions spaced">${['new','review'].includes(q.status)?btn(`${icon('spark')} ${q.plan?'重新核对':'分析并建议分派'}`,'analyze','secondary',`data-id="${q.id}"`):''}${q.status==='review'&&can(s,'business-review')&&(!q.reviewer||q.reviewer===staffId(s)||s.session.role==='owner')?btn('审批方案并创建任务','approve-order','',`data-id="${q.id}"`):''}${support?btn('准备回复草稿','reply','ghost',`data-id="${q.id}"`):''}</div>${s.replies.filter(r=>r.q===q.id).map(r=>`<div class="notice spaced"><b>已保存的回复草稿</b><br>${esc(r.text)}<br><small>草稿未发送；需要在客户对话中确认发送。</small></div>`).join('')}</section>`).join('')}</div>`;}
function approvals(){const order=can(s,'business-review')?s.inquiries.filter(q=>q.status==='review'&&(!q.reviewer||q.reviewer===staffId(s)||s.session.role==='owner')):[];return heading('HUMAN IN CONTROL','重要的决定，由人确认。','审批检查职位、申请状态与自审批限制；每次处理留下记录。')+`<section class="card"><div class="card-head"><h2>业务方案</h2>${badge(order.length+' 项待处理','orange')}</div>${order.map(q=>`<div class="row"><div><h3>${esc(q.customer)} · ${esc(q.id)}</h3><p class="muted">${esc(q.plan.reason)} 建议 ${esc(person(q.plan.assignee))} 负责。</p></div>${btn('审批并创建任务','approve-order','','data-id="'+q.id+'"')}</div>`).join('')||empty('当前没有需要你审批的客户方案。')}</section>${['leave','claims','ot'].map(k=>{const allowed=can(s,k==='claims'?'claim-review':'hr-review');if(!allowed)return '';const rs=visibleRequests(s,k).filter(r=>r.status==='pending');return `<section class="card"><div class="card-head"><h2>${({leave:'休假',claims:'报销',ot:'加班'})[k]}申请</h2>${badge(rs.length+' 项','gray')}</div>${rs.map(r=>requestRow(r,k,true)).join('')||empty('当前没有待审批申请。')}</section>`;}).join('')}`;}
function requestRow(r,k,review=false){return `<div class="row"><div><h3>${esc(person(r.staff))} · ${esc(r.id)}</h3><p style="font-size:11px" class="muted">${k==='claims'?`RM ${(+r.amount).toFixed(2)} · ${esc(r.merchant)} · ${r.amount>policy(s).claimLimit?`超过演示政策 RM ${policy(s).claimLimit}，需人工复核`:'在演示政策额度内'}`:k==='leave'?`${esc(r.from)} → ${esc(r.to)} · ${r.days} 天`:`${esc(r.date)} · ${r.hours} 小时${r.hours>policy(s).overtimeHours?` · 超过 ${policy(s).overtimeHours} 小时，模式异常需复核`:''}`}<br>${esc(r.reason||'')}</p></div><div class="row-end">${status(r.status)}${review?btn('批准','review','small',`data-kind="${k}" data-id="${r.id}" data-approved="yes"`)+btn('驳回','review','small danger',`data-kind="${k}" data-id="${r.id}" data-approved="no"`):''}</div></div>`;}
function people(){const labels={leave:'eLeave · 休假',claims:'eClaim · 报销',ot:'eOT · 加班',attendance:'Attendance',directory:'Directory',announcements:'公告',import:'人力资源表格'};if(!labels[tab]||(tab==='import'&&!can(s,'hr-import')))tab='leave';let body='';
 if(tab==='leave'){const used=s.leave.filter(l=>l.staff===staffId(s)&&l.status==='approved').reduce((n,l)=>n+l.days,0);body=`<div class="columns"><section class="card"><div class="card-head"><h2>休假申请</h2>${btn('申请休假','request','','data-kind="leave"')}</div>${visibleRequests(s,'leave').map(r=>requestRow(r,'leave')).join('')||empty('暂时没有休假申请。')}</section><section class="card"><h2>我的假期</h2><strong class="summary-number">${Math.max(0,policy(s).annualLeaveDays-used)} <small style="font-size:14px">天</small></strong><p class="muted">演示年假 ${policy(s).annualLeaveDays} 天，已使用 ${used} 天。不是法定权益计算。</p><div class="insight">批准的休假会进入订单人员检查和项目日历。提交申请时会提醒团队休假重叠与本人任务冲突。</div></section></div>`;}
 if(tab==='claims'||tab==='ot')body=`<section class="card"><div class="card-head"><h2>${tab==='claims'?'我的相关报销':'我的相关加班'}</h2>${btn(tab==='claims'?'上传收据 / 申请报销':'提前申请加班','request','',`data-kind="${tab}"`)}</div><div class="notice">${tab==='claims'?`支持收据照片本地预览和人工确认字段；OCR / AI 识别尚未接入。超过 RM ${policy(s).claimLimit} 会提示政策复核。`:`按申请的起止时间计算时数；超过 ${policy(s).overtimeHours} 小时会提示异常。请在加班开始前提交，审批不等同于工资计算。`}</div>${visibleRequests(s,tab).map(r=>requestRow(r,tab)).join('')||empty('目前没有相关记录。')}</section>`;
 if(tab==='attendance')body=`<div class="columns"><section class="card"><div class="card-head"><h2>我的考勤</h2>${btn('上班 / 下班打卡','clock')}</div>${s.attendance.filter(a=>a.staff===staffId(s)).map(a=>`<div class="row"><div><h3>${a.out?'下班已记录':'上班已记录'}</h3><p>${time(a.in)} ${a.out?' → '+time(a.out):''}</p></div>${badge(a.out?'已完成':'工作中')}</div>`).join('')||empty('今天还没有打卡记录。')}</section><section class="card"><h2>考勤说明</h2><p class="muted">按马来西亚时间记录本人打卡。演示不采集定位或生物识别。团队工资与法定工时规则需由企业另行配置。</p>${can(s,'hr-import')?`<h3>员工考勤记录</h3>${s.attendance.map(a=>`<div class="row"><span>${esc(person(a.staff))}</span><small>${time(a.in)}</small></div>`).join('')||empty('暂无员工打卡记录')}`:''}</section></div>`;
 if(tab==='directory')body=`<div class="grid3">${s.staff.map(e=>`<section class="card"><div class="avatar">${esc(e.name[0])}</div><h3 class="spaced">${esc(e.name)}</h3><p class="muted">${esc(e.role)} · ${esc(e.team)}</p><small>${esc(e.email)}</small><div class="footer-note">公开工作联系方式 · 无薪资和私人资料</div></section>`).join('')}</div>`;
 if(tab==='announcements')body=`<section class="card"><div class="card-head"><h2>企业公告</h2>${can(s,'announce')?btn('发布公告','announcement'):''}</div>${s.announcements.map(a=>`<div class="row"><div><h3>${esc(a.title)}</h3><p style="font-size:12px">${esc(a.text)}</p><small>发布人：${esc(a.by)}</small></div></div>`).join('')}</section>`;
 if(tab==='import')body=`<div class="columns"><section class="card"><h2>从熟悉的表格开始</h2><p class="muted">导入员工技能与可用工时，查看资源缺口。仅在本机分析，不上传文件。</p><div class="actions">${btn(`${icon('upload')} 选择 CSV 表格`,'import')}${btn('下载 CSV 模板','template','secondary')}</div><input type="file" id="hr-file" accept=".csv,text/csv" hidden><div class="notice spaced">字段：name, team, skill, capacity。capacity 表示可用小时（0–24）。请使用合成数据；此处分析不导入员工主档。</div><div id="import-result">${importRows.length?importAnalysis():empty('上传表格后会显示人员数量、技能分布和工时异常。')}</div></section><section class="card"><h2>业务建议怎么来？</h2><p class="muted">统计可用工时与技能；0 工时的人不会被视为可用资源。规则先检查缺失数据，再把需确认的问题交给 HR。</p><div class="insight"><strong>AI 分析接口预留</strong><br>当前为本地统计分析。生产版可用模型解释结果，但不能根据人员画像自动作出雇佣或纪律处分决定。</div></section></div>`;
 return heading('PEOPLE, IN CONTEXT','人事信息，连接每一天的工作。','People 为业务流程提供员工、休假与可用性上下文。')+`<div class="tabbar">${Object.entries(labels).filter(([k])=>k!=='import'||can(s,'hr-import')).map(([k,l])=>`<button class="${tab===k?'active':''}" data-action="tab" data-tab="${k}">${l}</button>`).join('')}</div>`+body;
}
function importAnalysis(){const cap=importRows.reduce((n,r)=>n+r.capacity,0),skills=[...new Set(importRows.map(r=>r.skill))];return `<div class="insight"><strong>已分析 ${importRows.length} 位员工</strong><br>总可用工时 ${cap} 小时 · 技能 ${skills.map(esc).join('、')}<br>${importRows.filter(r=>!r.capacity).length} 人没有可用工时，应在排期前确认。${skills.length<2?'技能集中，建议安排交叉培训。':'技能覆盖多个类别，可按实际订单需求调配。'}</div><div class="spaced">${importRows.map(r=>`<div class="row"><b>${esc(r.name)}</b><small>${esc(r.team)} · ${esc(r.skill)} · ${r.capacity} h</small></div>`).join('')}</div>`;}
function work(){const ts=visibleTasks(s);const ps=s.projects.filter(p=>can(s,'business-review')||ts.some(t=>t.customer===p.customer));return heading('WORK, WITH CLARITY','知道进展，也知道为什么卡住。','任务与客户关联，休假与资源安排同步考虑。',btn(`${icon('plus')} 今日工作记录`,'daily'))+customerUI.handoffs()+`<div class="grid2">${ps.map(p=>`<section class="card"><div class="card-head"><h2>${esc(p.name)}</h2>${badge(p.progress+'%','gray')}</div><small>客户 · ${esc(p.customer)}</small><div class="progress"><span style="width:${p.progress}%"></span></div><p style="font-size:12px">Monthly Focus · ${esc(p.focus)}</p><div class="insight warning"><strong>延期线索</strong><br>${esc(p.risk)}。这是合成项目基线，需结合实际工作记录确认。</div></section>`).join('')||'<div class="notice">你还没有关联项目。</div>'}</div><div class="card-head"><h2>任务看板</h2><small>仅显示本人或有权限的团队任务</small></div><div class="kanban">${['待开始','进行中','受阻'].map(st=>`<section class="kanban-col"><h3>${st} · ${ts.filter(t=>t.status===st).length}</h3>${ts.filter(t=>t.status===st).map(t=>`<div class="task-card">${badge(t.customer,'gray')}<h3>${esc(t.title)}</h3><p>${esc(person(t.assignee))} · ${esc(t.due)}</p>${t.blocked?`<div class="insight warning">${esc(t.blocked)}</div>`:''}<div class="spaced">${btn(st==='待开始'?'开始处理':st==='进行中'?'标记完成':'确认阻碍已解除','task','small secondary','data-id="'+t.id+'"')}</div></div>`).join('')||empty('暂无任务')}</section>`).join('')}</div>${ts.some(t=>t.status==='已完成')?`<section class="card spaced"><h2>已完成</h2>${taskRows(ts.filter(t=>t.status==='已完成'))}</section>`:''}<div class="columns spaced"><section class="card"><div class="card-head"><h2>Daily Work Status</h2>${badge('完成 / 下一步 / 阻碍','gray')}</div>${s.daily.filter(d=>can(s,'business-review')||d.staff===staffId(s)).map(d=>`<div class="row"><div><h3>${esc(person(d.staff))} · ${time(d.time)}</h3><p>已完成：${esc(d.done)}<br>下一步：${esc(d.next)}<br>阻碍：${esc(d.blocked||'无')}</p></div></div>`).join('')||empty('记录今天的工作，让团队少问一句「进展如何」。')}</section><section class="card"><div class="card-head"><h2>团队日历</h2>${badge('2026 · 10','gray')}</div><div class="calendar">${['一','二','三','四','五','六','日'].map(d=>`<div class="muted">${d}</div>`).join('')}${Array(3).fill('<div></div>').join('')}${Array.from({length:31},(_,i)=>`<div class="${s.leave.some(l=>l.status==='approved'&&l.from<=`2026-10-${String(i+1).padStart(2,'0')}`&&l.to>=`2026-10-${String(i+1).padStart(2,'0')}`)?'leave-day':''}">${i+1}</div>`).join('')}</div><p class="footer-note">绿底：团队已批准休假（仅显示是否有人休假）。下一公共假期样例：11 月 8 日 Deepavali；地区适用及补假需核实。</p><div class="notice">州属：${esc(companySettings(s).state)} · 假期为演示样例，尚未接入官方日历，不用于承诺交期。</div></section></div>`;}
function conversationTitle(key){
 if(!key.startsWith('dm:'))return '# '+key;
 const peer=conversationMembers(s,key).find(id=>id!==staffId(s));return person(peer);
}
function unreadCount(key){return unreadMessages(s).filter(m=>m.room===key).length;}
function openDirectPicker(){
 requirePermission(s,'chat');modal('发起私聊',`<p class="muted">选择同事，开始一对一对话。</p><div class="member-picker">${s.staff.filter(e=>e.id!==staffId(s)).map(e=>`<button class="member-pick" data-action="room" data-room="${directRoom(staffId(s),e.id)}"><span class="avatar">${esc(e.name[0])}</span><span><b>${esc(e.name)}</b><small>${esc(e.role)} · ${esc(e.team)}</small></span><span class="member-arrow">↗</span></button>`).join('')}</div>`);
}
function scrollMessages(){const el=$('.messages');if(el)el.scrollTop=el.scrollHeight;}
function hideMessage(){const b=$('#message-banner');b?.classList.remove('show');b?.replaceChildren();clearTimeout(messageTimer);}
function showBroadcast(id){
 if(s.session?.role==='customer')return;
 const b=publicBroadcasts(s).find(b=>b.id===id),banner=$('#message-banner');if(!b||!banner)return;
 clearTimeout(messageTimer);banner.classList.add('owner-broadcast');banner.innerHTML=`<button class="message-open" data-action="view-broadcast" data-id="${esc(b.id)}"><span class="avatar">${icon('bell')}</span><span class="message-preview"><b>企业主通知<small>${esc(b.by)} · 全体成员</small></b><strong class="broadcast-banner-title">${esc(b.title)}</strong><span>${esc(b.text)}</span></span></button><button class="icon-button" data-action="dismiss-message" aria-label="关闭企业通知">${icon('x')}</button>`;
 markBroadcastRead(s,b.id);persist();banner.classList.add('show');messageTimer=setTimeout(hideMessage,12000);
}
function notifyUnread(){if(s.session?.role==='customer')return;const bs=unreadBroadcasts(s);if(bs.length)showBroadcast(bs.at(-1).id);}
function broadcastHistory(){const bs=publicBroadcasts(s).slice().reverse();return bs.map(b=>`<button class="notification-item" data-action="view-broadcast" data-id="${esc(b.id)}"><b>${esc(b.title)} ${!(b.readBy||[]).includes(staffId(s))?' · 未读':''}</b><span>${esc(b.text.slice(0,100))}</span><small>企业主 ${esc(b.by)} · ${time(b.createdAt)}</small></button>`).join('')||'<p class="muted">企业主尚未发布公屏通知。</p>';}
function notificationList(){const ms=unreadMessages(s);return `<h3>企业主通知</h3>${broadcastHistory()}<h3 class="spaced">聊天未读 · ${ms.length}</h3>${ms.slice(-8).reverse().map(m=>`<button class="notification-item" data-action="room" data-room="${esc(m.room)}"><b>${esc(m.by)} · ${esc(conversationTitle(m.room))}</b><span>${esc(m.text.slice(0,90))}</span></button>`).join('')||'<p class="muted">暂无未读聊天。</p>'}`;}
function broadcast(){requirePermission(s,'broadcast');return heading('OWNER ANNOUNCEMENTS','重要通知，由企业主发出。','在专用窗口发布，所有成员的页面顶部都会弹出通知。',btn(`${icon('plus')} 发布通知`,'broadcast-compose'))+`<div class="columns"><section class="card"><div class="card-head"><h2>已发布通知</h2>${badge(publicBroadcasts(s).length+' 条','gray')}</div>${broadcastHistory()}</section><section class="card"><h2>公屏发布规则</h2><div class="permission-item"><b>仅企业主拥有发布权限</b><p>管理者及其他职位不能使用此窗口发布公屏消息。</p></div><div class="permission-item"><b>聊天与公屏分开</b><p>企业主的私聊和团队频道消息也不会触发公屏弹窗。只有这里发布的企业通知才会弹出。</p></div><div class="notice">演示在同源浏览器标签页间同步。成员登录后可看到尚未阅读的通知；跨设备发布需要实时后端。</div></section></div>`;}
function composeBroadcast(){requirePermission(s,'broadcast');modal('企业主专属 · 发布通知',`<form id="broadcast-form"><div class="broadcast-audience">${icon('people')} 发布至全体成员 · 页面顶部弹出</div><div class="field"><label for="broadcast-title">通知标题</label><input id="broadcast-title" name="title" required maxlength="80" placeholder="例如：今天的团队安排"></div><div class="field"><label for="broadcast-text">通知内容</label><textarea id="broadcast-text" name="text" required maxlength="1000" placeholder="输入需要让所有人看到的重要通知……"></textarea></div><div class="notice">只有在此窗口发布的消息会进入公屏。普通私聊、团队聊天和 People 公告均不会触发公屏弹窗。</div><button class="btn" type="submit">发布到公屏 ${icon('arrow')}</button></form>`);}

function chat(){
 const msgs=visibleMessages(s,room),own=staffId(s),dm=room.startsWith('dm:');
 const roomButton=(key,label,sub,avatar='')=>{const n=currentProfile(s).chatBadges?unreadCount(key):0;return `<button class="room ${key===room?'active':''}" data-action="room" data-room="${esc(key)}">${avatar?`<span class="avatar">${esc(avatar)}</span>`:''}<span class="room-info"><b>${esc(label)}</b><small>${esc(sub)}</small></span>${n?`<span class="unread-badge">${n}</span>`:''}</button>`;};
 return heading('NEXUS MESSENGER','想找的人，就在这里。','团队频道与成员私聊，一处连接。',`<div class="actions">${can(s,'broadcast')?btn(`${icon('bell')} 发布企业通知`,'broadcast-compose'):''}${btn(`${icon('plus')} 发起私聊`,'new-dm','secondary')}</div>`)+`<section class="card chat-layout"><aside class="chat-rooms"><div class="chat-section-title">团队频道</div>${['交付协作','全员交流'].map(r=>roomButton(r,'# '+r,r==='交付协作'?'订单、排期与交付':'企业日常与公告')).join('')}<div class="chat-section-title">成员私聊 <span>${s.staff.length-1} 位同事</span></div>${s.staff.filter(e=>e.id!==own).map(e=>{const key=directRoom(own,e.id),last=s.chats.filter(m=>m.room===key).at(-1);return roomButton(key,e.name,last?last.text.slice(0,25):e.role+' · 点击开始聊天',e.name[0]);}).join('')}</aside><div class="chat-main"><div class="chat-top"><div class="row-main"><div class="avatar">${dm?esc(conversationTitle(room)[0]):'#'}</div><div><b>${esc(conversationTitle(room))}</b><small class="chat-subtitle">${dm?'一对一私聊 · 仅聊天双方可见':'全员共享频道 · '+s.staff.length+' 位成员'}</small></div></div>${btn(`${icon('spark')} 总结`,'chat-summary','small secondary')}</div><div class="messages">${msgs.map(m=>`<div class="bubble-wrap ${m.staff===own?'mine':''}"><div class="avatar">${esc(m.by[0])}</div><div><div class="bubble"><small>${esc(m.by)} · ${esc(m.time)}</small>${esc(m.text)}</div>${m.staff===own&&dm?`<small class="message-read">${(m.readBy||[]).some(id=>id!==own)?'对方已读（演示）':'已保存在本机'}</small>`:''}</div></div>`).join('')||`<div class="conversation-empty"><div class="round-icon">${icon('chat')}</div><h3>和 ${esc(conversationTitle(room))} 打个招呼</h3><p>确认一个细节，分享一个进展。<br>你的第一条消息，从这里开始。</p></div>`}</div><form class="chat-form" id="chat-form"><label class="sr-only" for="chat-text">消息内容</label><input id="chat-text" name="text" required maxlength="2000" autocomplete="off" placeholder="${dm?'发消息给 '+esc(conversationTitle(room))+'……':'输入消息，与团队保持同步……'}"><button class="btn" type="submit">发送 ${icon('arrow')}</button></form></div></section><div class="notice">浏览器内原型：同源标签页同步聊天未读状态；公屏仅显示企业主通过专用窗口发布的通知。不支持跨设备聊天。私聊展示范围仅限参与者；管理者最高业务权限不开放他人私聊。真实身份、实时后端与安全隔离待接入。</div>`;
}

function connect(){const allowed=can(s,'manage-connectors');return heading('A CONNECTED BUSINESS','让工具之间，也能好好合作。','接口契约已整理；所有第三方连接目前均为模拟，实际能力需逐项确认。')+`<div class="notice">${allowed?'你可以配置全部连接的演示状态。':'财务仅可查看支付与会计接口。'} 不在浏览器存储 API 密钥。点击「模拟测试」只验证示例事件，不发起真实交易。</div><div class="grid3">${connectors.filter(c=>allowed||['payments','accounting'].includes(c.id)).map(c=>`<section class="card connector"><div class="card-head"><div class="brand-icon">${c.brand}</div>${badge(s.connections[c.id]?'模拟测试已通过':'未接入',s.connections[c.id]?'':'gray')}</div><h3>${c.name}</h3><p>${c.desc}</p><div class="provider">${c.provider}</div><small>数据范围 · ${c.scope}</small><div class="actions spaced">${btn('查看接口','connector','small secondary',`data-id="${c.id}"`)}${btn('模拟测试','test-connector','small',`data-id="${c.id}"`)}</div></section>`).join('')}</div><section class="card spaced"><h2>一个可复用的集成入口</h2><p class="muted">Orbyte 身份 → 授权范围 → 连接器 → 标准业务事件 → 审批 → 结果与审计。供应商适配层将第三方事件转换为统一结构，避免每个企业重新定制。</p><div class="insight">生产接口要求租户隔离、服务端授权、Webhook 签名验证和幂等处理。这里提供契约与模拟入口，不提供可收款或可发工资的后端。</div></section>`;}
function logs(){const ls=visibleLogs(s),sum=monthlySummary(s);return heading('EVERY ACTION, ACCOUNTABLE','有记录，才有下一次改进。','记录重要请求、审批和错误；月报只使用当前职位可查看的事件。',btn(`${icon('spark')} 生成本月复盘`,'monthly','secondary'))+`<div class="stats">${stat('可见事件',ls.length,'当前职位可访问记录','logs')}${stat('本月审批',sum.approvals,sum.month+' · MYT','check')}${stat('本月错误',sum.errors,'操作被拦截或验证失败','bell')}${stat('本月分析',sum.analyses,'生成建议，不代表已执行','spark')}</div><section class="card"><div class="card-head"><h2>活动记录</h2>${btn('导出可见日志','export-logs','ghost')}</div>${ls.map(l=>`<div class="row"><div class="row-main"><div class="round-icon ${l.type==='error'?'orange':''}">${icon(l.type==='approval'?'check':l.type==='error'?'bell':'logs')}</div><div class="log-detail"><h3>${esc(l.title)}</h3><p>${esc(l.detail)}</p><p>${esc(l.actor)} · ${time(l.time)} MYT</p></div></div>${badge(({approval:'审批',analysis:'分析',request:'请求',error:'异常',transaction:'交易'})[l.type]||l.type,l.type==='error'?'red':'gray')}</div>`).join('')||empty('还没有可见事件。')}</section><div class="notice">这是本地可修改的演示日志，不能用作防篡改审计或交易凭证。生产版需服务端追加式事件、租户范围、关联 ID 和保留策略。</div>`;}
function strategy(){return heading('THE PRODUCT, NOT JUST THE PLATFORM','把「追着人问」变成「流程接得住」。','产品定位、权限边界与比赛路线，放在同一个地方。')+`<div class="columns"><div><section class="card strategy-block"><div class="eyebrow">FOCUS FIRST</div><h2 class="spaced">Nexus · 消息到履约</h2><p>首批面向 5–20 人的小型印刷、定制礼品和服务团队（目标客群假设，待访谈验证）。一个人兼顾客服、排期与跟单，真正的负担是「消息中答应的事，没有变成有人负责的工作」。</p><div class="insight"><strong>我们的新能力</strong><br>客户消息 → 结构化需求 → 检查库存、休假和任务 → 建议分派 → 人工审批 → 创建任务 → 留下可追溯结果。</div><h3>为什么适合马来西亚 SME？</h3><p>采用你笔记中的 WhatsApp 与表格工作习惯；界面先提供中文和易认英文模块名，后续验证 Bahasa Melayu / English 文案。用 RM 显示金额，以 MYT 记录事件；排期要考虑州属与已核实公共假期。网页移动适配，减少额外培训。</p><p>背景证据：DOSM 2024 报告显示 MSME 贡献 39.5% GDP。这个宏观数据说明市场重要性，不能证明本产品已节省时间。<a href="https://www.dosm.gov.my/portal-main/release-content/micro-small--medium-enterprises-msmes-performance-2024" target="_blank" rel="noopener">查看 DOSM 来源 ↗</a></p><h3>避免比赛方向偏离</h3><p>比赛笔记明确禁止复制 Orbyte 已有 HR／行政能力。People、Work 和 Connect 在此用作平台上下文的模拟；路演重点是新的客户履约自动化，而不是把 HR 模块数量当成创新。</p><p><a href="https://www.orbyte.my/platform" target="_blank" rel="noopener">Orbyte 平台边界 ↗</a> · <a href="https://app.notion.com/p/40083c8a3210809fb2d9dd7303019085" target="_blank" rel="noopener">比赛笔记 ↗</a></p></section><section class="card strategy-block"><h2>验证与增长路线</h2><div class="permission-item"><b>01 · 黑客松 MVP</b><p>跑通一条加急订单的触发、检查、建议、审批和任务闭环。使用合成数据与规则，证明价值与人的控制权。</p></div><div class="permission-item"><b>02 · 真实小团队试点</b><p>访谈 5 家目标企业；用同一批订单对比人工与产品流程。测中位处理耗时、遗漏率、建议修改率，跟踪异常，不把目标包装成成果。</p></div><div class="permission-item"><b>03 · 平台与渠道接通</b><p>获取 Orbyte 接口合同；先接企业 WhatsApp 消息和一个业务数据源，再做服务端权限、事件幂等与审核。</p></div><div class="permission-item"><b>04 · 可复用行业模板</b><p>从印刷扩展到礼品、维修和预约服务。用字段、政策、角色与工作流配置适配行业，而不是为每家企业重写系统。</p></div><h3>商业模式假设</h3><p>基础套餐按企业／月收费，包含少量成员与流程次数；进阶版按工作流量和连接器收费。价格需经付费意愿访谈验证；WhatsApp 与模型成本需另计。优先通过 Orbyte 合作伙伴分销。</p></section></div><aside><section class="card"><h2>职位与信息边界</h2>${Object.entries(roles).map(([k,r])=>`<div class="permission-item"><b>${r.label}</b><p>${({owner:'最高业务权限，独享公屏通知发布；不能审批自己的申请，私聊仅聊天双方可见。',manager:'全局业务、人事、财务、审批与全部连接器；不能发布企业主公屏通知，私聊仅聊天双方可见。',hr:'员工导入、考勤、休假加班审核；不查看客户订单和付款。',finance:'报销政策复核、支付与会计接口；不读取休假原因或团队聊天之外的私密资料。',employee:'本人申请、本人任务和工作记录；公开通讯录、公告及共享聊天。',support:'客户收件箱、回复草稿与分派建议；无业务最终审批或付款权限。'})[k]}</p></div>`).join('')}</section><section class="card strategy-block"><h2>SDG，落实到可测指标</h2><p><strong>8.2 / 8.3</strong>：每单处理分钟、每人可完成订单、无需培训完成任务比例。</p><p><strong>10</strong>：移动端与低数字熟练度人员的任务成功率；不使用隐私数据排斥员工。</p><p><strong>12</strong>：缺货／重复采购警报与返工材料量。环保改善需收集实测数据，不能凭自动化直接宣称减排。</p><div class="notice">试点目标（非已实现结果）：订单准备时间减少 30%，关键步骤遗漏减少 50%。</div></section></aside></div>`;}
function requestModal(kind){const isLeave=kind==='leave',isClaim=kind==='claims';modal(isLeave?'申请休假':isClaim?'收据与报销':'提前申请加班',`<form id="request-form" data-kind="${kind}">${isLeave?`<div class="form-grid"><div class="field"><label for="req-from">开始日期</label><input id="req-from" type="date" name="from" required></div><div class="field"><label for="req-to">结束日期</label><input id="req-to" type="date" name="to" required></div></div><div class="notice">演示按日历天计假，不扣除周末与公共假期。真实政策需接入 Orbyte。重叠休假与任务会在提交后提示。</div>`:isClaim?`<div class="field"><label for="receipt">收据照片（可选）</label><input id="receipt" type="file" accept="image/png,image/jpeg,image/webp"></div><div id="receipt-preview"></div><div class="notice">收据识别服务未启用；请人工确认以下字段。照片仅在当前窗口预览，不存储、不上传。</div><div class="form-grid"><div class="field"><label for="merchant">商户</label><input id="merchant" name="merchant" maxlength="100" required></div><div class="field"><label for="amount">金额 RM</label><input id="amount" name="amount" type="number" min="0.01" max="100000" step="0.01" required></div></div>`:`<div class="field"><label for="ot-date">加班日期</label><input id="ot-date" name="date" type="date" required></div><div class="form-grid"><div class="field"><label for="ot-start">开始</label><input id="ot-start" name="start" type="time" required></div><div class="field"><label for="ot-end">结束（同一天）</label><input id="ot-end" name="end" type="time" required></div></div><div class="notice">申请时间必须早于加班开始。需事先审批；本原型不计算法定工资或跨夜工时。</div>`}<div class="field"><label for="reason">${isClaim?'用途说明':'申请原因'}</label><textarea id="reason" name="reason" required maxlength="800"></textarea></div><button class="btn" type="submit">提交至审批</button></form>`);}
async function action(a,el){if(s.session?.role==='customer'&&!['logout','close'].includes(a))throw Error('客户账户不能操作企业内部模块。');switch(a){
case 'login-audience':if(!['staff','customer'].includes(el.dataset.audience))throw Error('未知登录入口');loginAudience=el.dataset.audience;render();document.querySelector(`[data-action=login-audience][data-audience="${loginAudience}"]`)?.focus();break;
case 'customer-thread':requirePermission(s,'customer-support');customerUI.setCustomer(el.dataset.customer);render();break;
case 'customer-to-inquiry':customerUI.compose(el.dataset.customer,el.dataset.message);break;
case 'account-menu':accountUI.openMenu();break;
case 'settings-tab':{const selected=el.dataset.tab;accountUI.setTab(selected);render();document.querySelector(`[data-action=settings-tab][data-tab="${selected}"]`)?.focus({preventScroll:true});break;}
case 'settings-open':accountUI.setTab(el.dataset.tab);page='settings';render();window.scrollTo({top:0,behavior:'instant'});focusPage();break;
case 'avatar-upload':$('#avatar-file').click();break;
case 'avatar-remove':saveAvatar(s,'');persist();render();toast('头像已移除。');break;
case 'export-profile':download('nexus-my-data.json',JSON.stringify(personalExport(s),null,2),'application/json');break;
case 'logout':close();s.session=null;room='交付协作';hideMessage();persist();render();toast('已退出此工作空间。');break;
case 'role':selectedRole=el.dataset.id;render();document.querySelector(`[data-action=role][data-id="${selectedRole}"]`)?.focus({preventScroll:true});break;
case 'nav':page=el.dataset.page;if(page==='chat'){markConversationRead(s,room);persist();}render();window.scrollTo({top:0,behavior:'instant'});focusPage();break;
case 'tab':tab=el.dataset.tab;render();document.querySelector(`[data-action=tab][data-tab="${tab}"]`)?.focus({preventScroll:true});break;
case 'menu':toggleNavigation();break;
case 'close':close();break;
case 'switch':close();s.session=null;room='交付协作';hideMessage();persist();render();break;
case 'notifications':modal('消息与待办',`${notificationList()}`+`<p class="muted">你有 ${visibleTasks(s).filter(t=>t.status==='受阻').length} 项任务受阻。请查看任务详情。审批角色可在审批中心查看待处理请求。</p>${can(s,'approvals')?btn('打开审批中心','nav','','data-page="approvals"'):''}`);break;
case 'analyze':planInquiry(s,el.dataset.id);persist();render();toast('业务信息已核对，建议已生成，等待人工决定。');break;
case 'approve-order':approveInquiry(s,el.dataset.id);persist();render();toast('审批已完成，任务已创建；如有阻碍，请在项目页继续跟进。');break;
case 'review':reviewRequest(s,el.dataset.kind,el.dataset.id,el.dataset.approved==='yes');persist();render();toast('审批结果已记录。');break;
case 'request':requestModal(el.dataset.kind);break;
case 'daily':modal('记录今日工作',`<form id="daily-form"><div class="field"><label for="daily-done">今天完成了什么？</label><textarea id="daily-done" name="done" required maxlength="1500"></textarea></div><div class="field"><label for="daily-next">下一步做什么？</label><input id="daily-next" name="next" required maxlength="500"></div><div class="field"><label for="daily-blocked">有什么阻碍？</label><input id="daily-blocked" name="blocked" maxlength="500" placeholder="没有可以留空"></div><button class="btn" type="submit">保存工作记录</button></form>`);break;
case 'task':{requirePermission(s,'work');const t=visibleTasks(s).find(t=>t.id===el.dataset.id);if(!t)throw Error('无权操作此任务');if(t.status==='受阻'&&!can(s,'business-review'))throw Error('请由主管确认库存或其他阻碍已经解除。');t.status=({'待开始':'进行中','进行中':'已完成','受阻':'待开始'})[t.status]||t.status;if(t.status==='待开始')t.blocked='';addLog(s,'request','任务状态已更新',t.title+' → '+t.status,'operations',t.assignee);persist();render();break;}
case 'clock':{const own=staffId(s),open=s.attendance.find(a=>a.staff===own&&!a.out);if(open)open.out=new Date().toISOString();else s.attendance.push({id:crypto.randomUUID(),staff:own,in:new Date().toISOString(),out:null});addLog(s,'request',open?'下班打卡':'上班打卡','考勤已记录','hr');persist();render();break;}
case 'room':visibleMessages(s,el.dataset.room);room=el.dataset.room;page='chat';if($('#modal').open)close();hideMessage();markConversationRead(s,room);persist();render();scrollMessages();break;
case 'new-dm':openDirectPicker();break;
case 'dismiss-message':hideMessage();break;
case 'broadcast-compose':composeBroadcast();break;
case 'view-broadcast':{const b=markBroadcastRead(s,el.dataset.id);hideMessage();persist();modal('企业主通知',`<div class="notice">企业主 ${esc(b.by)} · ${time(b.createdAt)} MYT · 全体成员</div><h2>${esc(b.title)}</h2><p class="broadcast-full-text">${esc(b.text)}</p>`);break;}
case 'chat-summary':{requirePermission(s,'chat');const ms=visibleMessages(s,room).slice(-10);const mentions=ms.filter(m=>/库存|休假|交期|审批|缺货|阻碍/.test(m.text));addLog(s,'analysis','生成对话摘要',room.startsWith('dm:')?'本人参与的私聊':room,'private-chat');persist();modal('对话摘要 · 规则演示',`<div class="notice">仅处理当前授权对话最近 ${ms.length} 条消息；下方为摘录，不是模型生成结论。</div>${(mentions.length?mentions:ms).map(m=>`<div class="permission-item"><b>${esc(m.by)}</b><p>${esc(m.text)}</p></div>`).join('')||empty('尚无可总结消息')}<div class="insight">建议下一步：将涉及库存、交期或休假的信息放入业务流程核对，重要决定仍需审批。</div>`);break;}
case 'new-inquiry':customerUI.compose();break;
case 'reply':{requirePermission(s,'customer-support');const q=s.inquiries.find(q=>q.id===el.dataset.id);const ai=analyzeMessage(q.text);modal('客户回复 · 待人工确认',`<div class="notice">${esc(ai.note)}<br>分类：${esc(ai.intent)} · 路由：${esc(ai.route)}</div><form id="reply-form" data-id="${q.id}"><div class="field"><label for="reply-text">可编辑回复草稿</label><textarea id="reply-text" name="text" required maxlength="2000">${esc(ai.reply)}</textarea></div><button class="btn" type="submit">保存草稿（不发送）</button></form>`);break;}
case 'connector':{requirePermission(s,'connect');const c=connectors.find(c=>c.id===el.dataset.id);if(!can(s,'manage-connectors')&&!['payments','accounting'].includes(c.id))throw Error('无权查看此连接');modal(c.name+' · 接口契约',`<div class="notice">这是拟议的内部接口，不是 Orbyte 或供应商已公开承诺的端点。当前静态站未实现这些 HTTP 服务。</div><div class="code">POST ${c.endpoint}</div><p>数据范围：${c.scope}</p><div class="code">{ "tenant_id": "demo-kita", "event_id": "evt-unique", "source": "${c.id}", "payload": { "mode": "sandbox" } }</div><p class="muted">服务端流程：验证签名与租户 → 去重事件 → 检查权限 → 路由审批 → 写入审计。</p><p class="footer-note">供应商：${c.provider}。API 版本、字段、授权方式、可用范围需接入时逐项确认。</p>`);break;}
case 'test-connector':{requirePermission(s,'connect');if(!can(s,'manage-connectors')&&!['payments','accounting'].includes(el.dataset.id))throw Error('无权测试此连接');s.connections[el.dataset.id]=new Date().toISOString();addLog(s,el.dataset.id==='payments'?'transaction':'request','模拟连接测试通过',el.dataset.id+' · 示例事件；无真实网络调用', ['payments','accounting'].includes(el.dataset.id)?'finance':'operations');persist();render();toast('示例事件已记录，真实第三方连接仍未启用。');break;}
case 'import':requirePermission(s,'hr-import');$('#hr-file').click();break;
case 'template':download('employee-template.csv','\uFEFFname,team,skill,capacity\nAmir,运营,印刷,5\nDaniel,运营,印刷,0\nNur,运营,客户服务,5\n','text/csv');break;
case 'monthly':{const m=monthlySummary(s);modal('本月复盘 · '+esc(m.month),`<div class="notice">基于你可见的 ${m.count} 条本月事件。规则生成，未连接 AI 模型；非完整财务报表。</div><div class="permission-item"><b>做得好的地方</b><p>${m.approvals?`${m.approvals} 次审批留下记录，关键操作有人确认。`:'数据尚少，暂时不能判断审批效果。'} ${m.analyses?`${m.analyses} 次分析把业务检查放在执行之前。`:''}</p></div><div class="permission-item"><b>需要改善的地方</b><p>${m.errors?`出现 ${m.errors} 次验证或操作异常，建议检查原因并完善字段提示。`:'目前没有可见错误记录；这不代表没有业务风险。'} 仍需跟踪缺货与等待客户确认造成的阻碍。</p></div><div class="insight"><strong>下个月可做的三件事</strong><br>1. 为加急订单设置库存检查。<br>2. 每周查看休假与交付冲突。<br>3. 记录每单实际耗时，对比上线前基线。</div>`);addLog(s,'analysis','生成本月复盘',m.month+' · 基于当前可见事件');persist();break;}
case 'export-logs':download('orbyte-visible-events.json',JSON.stringify(visibleLogs(s),null,2),'application/json');break;
case 'announcement':requirePermission(s,'announce');modal('发布企业公告',`<form id="announcement-form"><div class="field"><label for="ann-title">标题</label><input id="ann-title" name="title" required maxlength="120"></div><div class="field"><label for="ann-text">内容</label><textarea id="ann-text" name="text" required maxlength="2000"></textarea></div><button class="btn" type="submit">发布到演示工作空间</button></form>`);break;
}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;try{if(el.dataset.action==='nav'&&$('#modal').open)close();await action(el.dataset.action,el);}catch(err){recordError(err);}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;const f=Object.fromEntries(new FormData(form));for(const k of Object.keys(f))if(typeof f[k]==='string')f[k]=f[k].trim();try{if(s.session?.role==='customer'&&form.id!=='customer-message-form')throw Error('客户账户不能提交内部表单。');switch(form.id){
case 'profile-form':saveProfile(s,f);persist();render();toast('个人资料已保存。');return;
case 'preferences-form':savePersonalPreferences(s,f);persist();render();toast('个人偏好已保存并应用。');return;
case 'company-form':saveCompanySettings(s,f);persist();render();toast('企业资料已保存。');return;
case 'policies-form':savePolicies(s,f);persist();render();toast('审批规则已保存并生效。');return;
case 'customer-login-form':{migrateCustomerService(s);const customer=s.customers.find(c=>c.id===f.customerId);if(!customer||!f.name||f.name.length>40)throw Error('请选择客户并填写称呼');s.session={role:'customer',customerId:customer.id,name:f.name};persist();render();return;}
case 'customer-message-form':{sendCustomerMessage(s,form.dataset.customer,f.text);persist();render();const messages=$('.customer-messages');if(messages)messages.scrollTop=messages.scrollHeight;toast('消息已发送到客户会话。');return;}
case 'login-form':if(!roles[selectedRole])throw Error('请选择有效职位');if(!f.name)throw Error('请输入姓名');s.session={role:selectedRole,name:f.name};s.industry=f.industry;persist();render();notifyUnread();return;
case 'chat-form':{sendMessage(s,room,f.text);markConversationRead(s,room);persist();render();scrollMessages();toast('消息已发送到当前对话。');return;}
case 'broadcast-form':{const b=publishBroadcast(s,f.title,f.text);persist();close();render();showBroadcast(b.id);return;}
case 'inquiry-form':createSupportInquiry(s,f);close();persist();render();toast('请求已交给审批负责人，建议执行员工也可在项目页查看。');return;
case 'reply-form':requirePermission(s,'customer-support');if(!f.text)throw Error('回复不能为空');s.replies.push({q:form.dataset.id,text:f.text});addLog(s,'request','客户回复草稿已保存',form.dataset.id+' · 未对外发送');close();break;
case 'daily-form':if(!f.done||!f.next)throw Error('请填写完成事项与下一步');s.daily.unshift({...f,staff:staffId(s),time:new Date().toISOString()});addLog(s,'request','每日工作记录已保存',f.blocked?'阻碍：'+f.blocked:'无新增阻碍');close();break;
case 'request-form':{const kind=form.dataset.kind;const r={id:kind[0].toUpperCase()+'-'+crypto.randomUUID().slice(0,6),staff:staffId(s),status:'pending',reason:f.reason};if(!f.reason)throw Error('请填写原因');let notes=[];
 if(kind==='leave'){if(!f.from||!f.to||f.to<f.from)throw Error('请检查休假起止日期');const days=Math.round((new Date(f.to)-new Date(f.from))/86400000)+1;if(days>policy(s).annualLeaveDays)throw Error(`超过演示年假额度 ${policy(s).annualLeaveDays} 天`);if(s.leave.some(l=>l.staff===r.staff&&l.status!=='rejected'&&l.from<=f.to&&l.to>=f.from))throw Error('与本人已提交或已批准的休假重叠');Object.assign(r,{from:f.from,to:f.to,days});if(s.leave.some(l=>l.status==='approved'&&l.from<=f.to&&l.to>=f.from))notes.push('团队已有成员同期休假');if(s.tasks.some(t=>t.assignee===r.staff&&t.status!=='已完成'&&t.due>=f.from&&t.due<=f.to))notes.push('本人任务交期与休假重叠');}
 else if(kind==='claims'){if(!f.merchant||!Number.isFinite(+f.amount)||+f.amount<=0||+f.amount>100000)throw Error('请确认商户和金额');Object.assign(r,{merchant:f.merchant,amount:+f.amount});if(r.amount>policy(s).claimLimit)notes.push(`超过演示政策 RM ${policy(s).claimLimit}，请财务复核`);}
 else if(kind==='ot'){const start=new Date(`${f.date}T${f.start}:00+08:00`),end=new Date(`${f.date}T${f.end}:00+08:00`);const hours=(end-start)/3600000;if(!Number.isFinite(hours)||hours<=0||hours>12)throw Error('请确认加班时间，同日最多 12 小时');if(start<=new Date())throw Error('加班需提前申请，开始时间必须在未来');Object.assign(r,{date:f.date,hours,start:f.start,end:f.end});if(hours>policy(s).overtimeHours)notes.push(`加班超过 ${policy(s).overtimeHours} 小时，需复核异常模式`);}
 else throw Error('未知申请');s[kind].unshift(r);addLog(s,'request','已提交'+({leave:'休假',claims:'报销',ot:'加班'})[kind]+'申请',r.id+(notes.length?' · '+notes.join('；'):''),kind==='claims'?'finance':'hr');close();if(notes.length)toast('已提交；提醒：'+notes.join('；'));break;}
case 'announcement-form':requirePermission(s,'announce');if(!f.title||!f.text)throw Error('请输入完整公告');s.announcements.unshift({...f,id:crypto.randomUUID(),by:s.session.name});addLog(s,'request','企业公告已发布',f.title);close();break;
default:return;
}persist();render();}catch(err){recordError(err);}});
document.addEventListener('change',async e=>{try{if(e.target.id==='avatar-file'){const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>450000)throw Error('头像请选择 450 KB 以内的 PNG / JPG / WebP');const reader=new FileReader();const avatar=await new Promise((resolve,reject)=>{reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('头像读取失败'));reader.readAsDataURL(file);});saveAvatar(s,avatar);persist();render();toast('头像已更新。');}if(e.target.id==='hr-file'){requirePermission(s,'hr-import');const file=e.target.files[0];if(!file)return;if(file.size>1024*1024)throw Error('CSV 文件请控制在 1 MB 内');importRows=parseCSV(await file.text());addLog(s,'analysis','人力资源表格分析完成',`${importRows.length} 行 · 文件未上传`,'hr');persist();render();toast('表格分析完成。');}if(e.target.id==='receipt'){const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('请选择 5 MB 以内的 PNG / JPG / WebP');const url=URL.createObjectURL(file);$('#receipt-preview').innerHTML=`<img class="receipt-preview" alt="待人工确认的收据预览" src="${url}">`;$('#modal').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}}catch(err){recordError(err);}});
function persistCustomerDraft(draft,focused,modalOpen){if(modalOpen)return;render();const input=$('#customer-message-input');if(input){input.value=draft;if(focused)input.focus();}const messages=$('.customer-messages');if(messages)messages.scrollTop=messages.scrollHeight;}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
window.addEventListener('storage',e=>{
 if(e.key!==KEY||!e.newValue)return;
 try{const next=JSON.parse(e.newValue);if(next.version!==1)return;
 const session=s.session,known=new Set((s.broadcasts||[]).map(b=>b.id));s={...next,session};migrateCustomerService(s);
 if(!session){render();return;}
 if(session.role==='customer'||(can(s,'customer-support')&&page==='inbox')){const draft=$('#customer-message-input')?.value||'',focused=document.activeElement===$('#customer-message-input'),modalOpen=$('#modal').open;persistCustomerDraft(draft,focused,modalOpen);return;}
 const arrived=unreadBroadcasts(s).filter(b=>!known.has(b.id));
 if(page==='chat'&&markConversationRead(s,room))persist();
 if(page==='chat'){
  const input=$('#chat-text'),draft=input?.value||'',focused=document.activeElement===input;
  render();if($('#chat-text')){$('#chat-text').value=draft;if(focused)$('#chat-text').focus();}scrollMessages();
 }else{
  const nav=$('[data-action="nav"][data-page="chat"]');if(nav){nav.querySelector('.count')?.remove();const n=currentProfile(s).chatBadges?unreadMessages(s).length:0;if(n)nav.insertAdjacentHTML('beforeend',`<b class="count">${n}</b>`);}
 }
 if(arrived.length)showBroadcast(arrived.at(-1).id);
 }catch{}
});
render();
notifyUnread();
